<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Receipt {{ $document->receipt_no }}</title><link rel="stylesheet" href="{{ asset('css/academy.css') }}"><style>@media print{.print-actions{display:none!important}body{background:#fff}.receipt{box-shadow:none!important;border-color:#bbb!important}}body{padding:30px}.receipt{max-width:720px;margin:35px auto;padding:38px;border:1px solid #e2e8e4;border-radius:12px;background:white}.receipt-top{display:flex;justify-content:space-between;border-bottom:2px solid #1a725b;padding-bottom:20px}.receipt-top h1{font:800 23px Manrope;margin:0}.receipt-top p,.receipt-meta small{font-size:11px;color:#75827a}.receipt-meta{text-align:right}.receipt-meta strong{display:block;font-size:15px}.receipt-table{margin:25px 0}.receipt-total{display:flex;justify-content:space-between;padding:17px 0;border-top:1px solid #e4eae6;font-weight:800}.receipt-note{padding-top:20px;border-top:1px dashed #ccd6cf;font-size:10px;color:#75827a}.print-actions{max-width:720px;margin:0 auto;text-align:right}</style></head><body><div class="print-actions"><button class="btn-primary" onclick="window.print()">Print receipt</button> <a class="btn-outline" href="{{ route('modules.index', 'payments') }}">Back to receipts</a></div><article class="receipt"><div class="receipt-top"><div><h1>{{ config('app.name', 'MSZ ERP') }}</h1><p>Official fee payment receipt · Pakistan</p></div><div class="receipt-meta"><small>RECEIPT NO.</small><strong>{{ $document->receipt_no }}</strong><small>{{ $document->paid_at->timezone('Asia/Karachi')->format('d M Y, h:i A') }}</small></div></div><div class="receipt-table"><table><tbody><tr><th>Student</th><td>{{ $document->student->name }}</td><th>Admission ID</th><td>{{ $document->student->admission_no }}</td></tr><tr><th>Father / guardian</th><td>{{ $document->student->father_name }}</td><th>Mobile</th><td>{{ $document->student->guardian_phone }}</td></tr